    {
      "a_request": "R1",
      "b_asked": "자전거 운전자가 보행자 옆을 지날 때 지켜야 할 주의 의무",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "자전거를 이용하는 시민은 도로교통에 관한 법령을 준수하여 보행자에게 위해를 주는 일이 없도록 보행자에 주의하면서 운전하여야 한다. 또한 안전사고 예방을 위해 이용시설여건에 따라 자전거 운전 시 안전장비를 구비하여야 한다.",
          "b_ids": "자전거:제4조제2항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "자동차 운전자가 자전거 옆을 지날 때 지켜야 할 주의 의무",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "자동차운전자는 도로교통에 관한 법령에 따라 자전거운전자를 우선적으로 배려하여 자전거운전에 위험이 초래되지 않도록 충돌을 피할 수 있는 필요한 거리를 확보하여 자동차를 운전하여야 한다.",
          "b_ids": "자전거:제4조제4항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
